package org.eclipse.rdf4j.sail.lmdb.bulk;

import java.util.Locale;
import java.util.Objects;

/**
 * The codec applied to one tier of the bulk loader's intermediate files: either LZ4's fast compressor, its high-ratio
 * compressor at an explicit level, or no compression at all. {@link BulkCompression} pairs one of these per tier.
 * <p>
 * Every LZ4-compressed file stays readable regardless of the level it was written at, because the block format records
 * what the decompressor needs. Only {@link Kind#NONE} is different in kind, since those files carry no LZ4 framing.
 */
public record BulkCodec(Kind kind, int level) {

	/**
	 * Lowest level accepted by {@code LZ4Factory.highCompressor(int)}.
	 */
	public static final int MINIMUM_LEVEL = 1;

	/**
	 * Highest level accepted by {@code LZ4Factory.highCompressor(int)}.
	 */
	public static final int MAXIMUM_LEVEL = 17;

	private static final String FAST_TOKEN = "fast";
	private static final String NONE_TOKEN = "none";

	/**
	 * LZ4's fast compressor: the cheapest codec that still shrinks the file.
	 */
	public static final BulkCodec FAST = new BulkCodec(Kind.FAST, 0);

	/**
	 * No compression; the tier's files are written as raw bytes.
	 */
	public static final BulkCodec NONE = new BulkCodec(Kind.NONE, 0);

	public BulkCodec {
		Objects.requireNonNull(kind, "kind");
		if (kind == Kind.HIGH) {
			requireValidLevel(level);
		} else if (level != 0) {
			throw new IllegalArgumentException(kind + " does not carry a compression level");
		}
	}

	/**
	 * LZ4's high-ratio compressor at {@code level}.
	 *
	 * @param level a compression level between {@value #MINIMUM_LEVEL} and {@value #MAXIMUM_LEVEL}
	 */
	public static BulkCodec level(int level) {
		return new BulkCodec(Kind.HIGH, level);
	}

	/**
	 * Parses {@code fast}, {@code none} or a compression level. Surrounding whitespace and letter case are ignored.
	 *
	 * @throws IllegalArgumentException if the token is neither a known name nor a level in range
	 */
	public static BulkCodec parse(String token) {
		String normalized = Objects.requireNonNull(token, "token").trim().toLowerCase(Locale.ROOT);
		if (FAST_TOKEN.equals(normalized)) {
			return FAST;
		}
		if (NONE_TOKEN.equals(normalized)) {
			return NONE;
		}
		int parsed;
		try {
			parsed = Integer.parseInt(normalized);
		} catch (NumberFormatException e) {
			throw new IllegalArgumentException(
					"A compression tier must be " + FAST_TOKEN + ", " + NONE_TOKEN + ", or a level between "
							+ MINIMUM_LEVEL + " and " + MAXIMUM_LEVEL + ", but was: " + token);
		}
		return level(parsed);
	}

	/**
	 * The stable text form of this codec, as accepted by {@link #parse(String)}.
	 */
	public String token() {
		return switch (kind) {
		case FAST -> FAST_TOKEN;
		case NONE -> NONE_TOKEN;
		case HIGH -> Integer.toString(level);
		};
	}

	private static void requireValidLevel(int level) {
		// LZ4Factory.highCompressor(int) silently clamps out-of-range levels, so validate before it can hide a typo.
		if (level < MINIMUM_LEVEL || level > MAXIMUM_LEVEL) {
			throw new IllegalArgumentException(
					"Compression level must be between " + MINIMUM_LEVEL + " and " + MAXIMUM_LEVEL + ", but was: "
							+ level);
		}
	}

	@Override
	public String toString() {
		return token();
	}

	public enum Kind {
		/** LZ4's fast compressor. */
		FAST,
		/** No compression at all. */
		NONE,
		/** LZ4's high-ratio compressor at an explicit level. */
		HIGH
	}
}
